examples.template:
Column(horizontalAlignment = Alignment.End, verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3), modifier = Modifier.fillMaxWidth()) {
    MonarchReadReceipt(
        readers = readers.take({{displays.0.readerCount}}),
        display = MonarchReadReceiptDisplay.{{displays.0.display|pascal}},
    )
    MonarchReadReceipt(
        readers = readers.take({{displays.1.readerCount}}),
        display = MonarchReadReceiptDisplay.{{displays.1.display|pascal}},
    )
    MonarchReadReceipt(
        readers = readers.take({{displays.2.readerCount}}),
        display = MonarchReadReceiptDisplay.{{displays.2.display|pascal}},
    )
}

examples.code:
Column(horizontalAlignment = Alignment.End, verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3), modifier = Modifier.fillMaxWidth()) {
    MonarchReadReceipt(
        readers = readers.take(1),
        display = MonarchReadReceiptDisplay.Text,
    )
    MonarchReadReceipt(
        readers = readers.take(5),
        display = MonarchReadReceiptDisplay.Count,
    )
    MonarchReadReceipt(
        readers = readers.take(5),
        display = MonarchReadReceiptDisplay.Avatars,
    )
}

Column(horizontalAlignment = Alignment.End, modifier = Modifier.fillMaxWidth()) {
    MonarchReadReceipt(
        readers = readers,
        display = MonarchReadReceiptDisplay.Avatars,
        onShowReaders = { showReaders = true },
    )
}
